-- Athena saved query (Product_B2C_Intl)
-- ID: d0c5efcf-90f6-4820-996a-6e48ca8da29b
-- Name: User Behaviour Loop Funnel UI - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH base AS ( SELECT mri_session_id, CAST(__time AS TIMESTAMP) AS ts_time_utc, event_group, CASE WHEN event_name = 'payment instrument confirmed' THEN 'payment instrument confirmed' ELSE NULL END AS event_name FROM user_interaction.ui_ux_events WHERE __time >= TIMESTAMP '2026-04-27 00:00:00' AND __time < TIMESTAMP '2026-04-28 00:00:00' AND header_country = 'IND' AND LOWER(header_bu) = 'bus' AND event_src = 'Android' AND event_group IN ( 'common_home_screen_load', 'bus_home_screen_load', 'Hotel_offers_screen_load', 'srp_screen_load', 'sl_screen_load', 'bp_dp_screen_load', 'cust_info_load', 'payment_screen_load', 'payment_click_event', 'show_ticket_screen_load' ) ), labeled AS ( SELECT mri_session_id, ts_time_utc, CASE WHEN event_group ='common_home_screen_load' THEN 'Home' WHEN event_group = 'bus_home_screen_load' THEN 'BusHome' WHEN event_group = 'Hotel_offers_screen_load' THEN 'HotelsHome' WHEN event_group = 'srp_screen_load' THEN 'SRP' WHEN event_group = 'sl_screen_load' THEN 'SL' WHEN event_group = 'bp_dp_screen_load' THEN 'BP_DP_Load' WHEN event_group = 'cust_info_load' THEN 'CI' WHEN event_group = 'payment_screen_load' THEN 'Pay' WHEN event_group = 'payment_click_event' AND event_name = 'payment instrument confirmed' THEN 'AddPay' WHEN event_group = 'show_ticket_screen_load' THEN 'Confirm' -- ELSE event_group END AS step_label FROM base ), pay_sessions AS ( SELECT DISTINCT mri_session_id FROM labeled WHERE step_label = 'Pay' ), paths AS ( SELECT l.mri_session_id, ARRAY_JOIN( ARRAY_AGG(l.step_label ORDER BY l.ts_time_utc), ' > ' ) AS behaviour_path FROM labeled l -- INNER JOIN pay_sessions p ON l.mri_session_id = p.mri_session_id GROUP BY l.mri_session_id ) SELECT behaviour_path, COUNT(*) AS distinct_sessions FROM paths GROUP BY 1 ORDER BY 2 DESC, 1;
